solution.code:
interface Config {
  readonly host: string;
  readonly port: number;
}

type Mutable<T> = { -readonly [K in keyof T]: T[K] };

const c: Mutable<Config> = { host: 'localhost', port: 80 };
c.port = 443;
console.log(c.host, c.port);

