interface User { id: number; name: string; }

// BUG: trying to make fields optional by unioning undefined onto the value.
// This still REQUIRES each key to be present (just allows undefined values),
// which is not the same as Partial.
type LooseUser = { [K in keyof User]: User[K] | undefined };

const u: LooseUser = { name: 'Ada' }; // ERROR: 'id' is missing
console.log(u);

solution.code:
interface User { id: number; name: string; }

type PartialUser = { [K in keyof User]?: User[K] };

const u: PartialUser = { name: 'Ada' }; // now valid — id may be omitted
console.log(u);

type Stringify<T> = { [K in keyof T]: string };

function stringify<T extends object>(obj: T): Stringify<T> {
  const out: any = {};
  for (const key of Object.keys(obj)) {
    out[key] = String((obj as any)[key]);
  }
  return out;
}

const result = stringify({ id: 1, active: true });
console.log(result.id, result.active);
console.log(typeof result.id, typeof result.active);
